update public.oil_types set bulk_cost_per_litre = 4.4100, gallon_cost_per_litre = 6.3836 * coalesce(litres_per_gallon, 3.785) where code = '10';
update public.oil_types set bulk_cost_per_litre = 6.7900, gallon_cost_per_litre = 8.4683 * coalesce(litres_per_gallon, 3.785) where code = '11';
update public.oil_types set bulk_cost_per_litre = 10.8800 where code = '13';
update public.oil_types set bulk_cost_per_litre = 15.1150 where code = '18';

